  <h1>Crear una cuenta</h1>
  <p class="intro">Rellena el formulario para registrarte.</p>

  <!-- novalidate: la validación la hace el script, con las mismas reglas en todos los navegadores -->
  <form id="signup" action="#" method="post" novalidate>

