      <input type="text" id="email" name="email" inputmode="email" autocomplete="email"
             autocapitalize="off" autocorrect="off" spellcheck="false"
             required aria-required="true" aria-describedby="email-hint email-error">
      <p class="hint" id="email-hint">Se admiten direcciones internacionalizadas, p.&nbsp;ej. josé.dupont@société.fr</p>
