<script>
(function () {
  'use strict';

  var PASSWORD_MIN = 8;

  /* ---------- Dominios ---------- */

  // Caracteres ASCII que no pueden aparecer en un dominio escrito por la persona
  // (todo ASCII salvo letras, dígitos, guion y punto). Los caracteres no ASCII
  // se dejan pasar: los valida la conversión IDNA de más abajo.
  var FORBIDDEN_ASCII_IN_DOMAIN = /[\u0000-\u002C\u002F\u003A-\u0040\u005B-\u0060\u007B-\u007F]/;

  // Convierte U-labels en A-labels (UTS #46) con el analizador de URL del navegador.
  // Devuelve null si el dominio no es convertible.
  function domainToAscii(domain) {
    if (!domain || /\s/.test(domain) || FORBIDDEN_ASCII_IN_DOMAIN.test(domain)) {
      return null;
    }
    try {
      return new URL('http://' + domain + '/').hostname.toLowerCase();
    } catch (e) {
      return null;
    }
  }

  // Comprueba un nombre YA convertido a su forma ASCII (A-labels):
  // etiquetas de 1 a 63 octetos, nombre de 253 como máximo, y un TLD de
  // dos o más letras (sin tope propio de longitud) o un A-label «xn--».
  function isValidAsciiHostname(host) {
    if (!host || host.length > 253) { return false; }
    var labels = host.toLowerCase().split('.');
    if (labels.length < 2) { return false; }
    for (var i = 0; i < labels.length; i++) {
      var label = labels[i];
      if (label.length < 1 || label.length > 63) { return false; }
      if (!/^[a-z0-9-]+$/.test(label)) { return false; }
      if (label.charAt(0) === '-' || label.charAt(label.length - 1) === '-') { return false; }
    }
    var tld = labels[labels.length - 1];
    return /^[a-z]{2,}$/.test(tld) || /^xn--[a-z0-9-]+$/.test(tld);
  }

  /* ---------- Validadores: devuelven { error, normalized } ---------- */

  function validateFullname(raw) {
    if (!raw.trim()) {
      return { error: 'Introduce tu nombre completo.' };
    }
    return { error: '' };
  }

  function validateEmail(raw) {
    var value = raw.trim();
    if (!value) {
      return { error: 'Introduce tu dirección de correo electrónico.' };
    }
    if (/\s/.test(value)) {
      return { error: 'La dirección no puede contener espacios.' };
    }
    var at = value.indexOf('@');
    if (at === -1) {
      return { error: 'Falta el símbolo «@» en la dirección.' };
    }
    if (at !== value.lastIndexOf('@')) {
      return { error: 'La dirección solo puede contener un símbolo «@».' };
    }
    var local = value.slice(0, at);     // se acepta Unicode (RFC 6531) y símbolos como + o '
    var domain = value.slice(at + 1);
    if (!local) {
      return { error: 'Falta la parte anterior al símbolo «@».' };
    }
    if (!domain) {
      return { error: 'Falta el dominio después del símbolo «@».' };
    }
    var asciiDomain = domainToAscii(domain);
    if (!asciiDomain || !isValidAsciiHostname(asciiDomain)) {
      return { error: 'El dominio «' + domain + '» no es válido. Ejemplo: nombre@ejemplo.es' };
    }
    return { error: '', normalized: local + '@' + asciiDomain };
  }

  function validateWebsite(raw) {
    var value = raw.trim();
    if (!value) {
      return { error: '', normalized: '' };   // campo opcional
    }
    if (/\s/.test(value)) {
      return { error: 'La dirección del sitio web no puede contener espacios.' };
    }
    // Si no se indica esquema, se asume https://
    var candidate = /^[a-z][a-z0-9+.-]*:\/\//i.test(value) ? value : 'https://' + value;
    var url;
    try {
      url = new URL(candidate);   // convierte el dominio a A-labels (UTS #46)
    } catch (e) {
      return { error: 'Introduce una dirección web válida, p. ej. https://ejemplo.es' };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'La dirección debe empezar por http:// o https://' };
    }
    if (url.username || url.password) {
      return { error: 'La dirección no debe incluir usuario ni contraseña.' };
    }
    if (!isValidAsciiHostname(url.hostname)) {
      return { error: 'El dominio del sitio web no es válido, p. ej. https://ejemplo.es' };
    }
    return { error: '', normalized: url.href };
  }

  function validatePassword(raw) {
    if (!raw) {
      return { error: 'Introduce una contraseña.' };
    }
    if (Array.from(raw).length < PASSWORD_MIN) {
      return { error: 'La contraseña debe tener al menos ' + PASSWORD_MIN + ' caracteres.' };
    }
    return { error: '' };
  }

  /* ---------- Enlace con el formulario ---------- */

  var form = document.getElementById('signup');
  var status = document.getElementById('form-status');

  var fields = [
    { id: 'fullname', validate: validateFullname },
    { id: 'email',    validate: validateEmail,   hidden: 'email-ascii' },
    { id: 'website',  validate: validateWebsite, hidden: 'website-ascii' },
    { id: 'password', validate: validatePassword }
  ];

  fields.forEach(function (field) {
    field.input = document.getElementById(field.id);
    field.errorEl = document.getElementById(field.id + '-error');
    field.hiddenEl = field.hidden ? document.getElementById(field.hidden) : null;
    field.touched = false;

    field.input.addEventListener('blur', function () {
      field.touched = true;
      checkField(field);
    });
    field.input.addEventListener('input', function () {
      status.textContent = '';
      status.className = 'status';
      if (field.touched) { checkField(field); }
    });
  });

  function checkField(field) {
    var result = field.validate(field.input.value);
    if (result.error) {
      field.errorEl.textContent = result.error;
      field.input.setAttribute('aria-invalid', 'true');
    } else {
      field.errorEl.textContent = '';
      field.input.removeAttribute('aria-invalid');
    }
    if (field.hiddenEl) {
      field.hiddenEl.value = result.error ? '' : (result.normalized || '');
    }
    return !result.error;
  }

  form.addEventListener('submit', function (event) {
    var firstInvalid = null;
    fields.forEach(function (field) {
      field.touched = true;
      if (!checkField(field) && !firstInvalid) {
        firstInvalid = field;
      }
    });

    if (firstInvalid) {
      event.preventDefault();
      status.textContent = 'Revisa los campos marcados antes de continuar.';
      status.className = 'status ko';
      firstInvalid.input.focus();
      return;
    }

    // Página autónoma, sin servidor: se detiene el envío y se confirma en pantalla.
    // Con un servidor real, elimina la línea siguiente y ajusta el atributo «action»;
    // se enviarán los valores tal como se escribieron y, además, email_ascii y
    // website_ascii con el dominio convertido a A-labels.
    event.preventDefault();
    status.textContent = '¡Gracias! Los datos son válidos y el registro está listo para enviarse.';
    status.className = 'status ok';
  });

  /* ---------- Mostrar / ocultar la contraseña ---------- */

  var toggle = document.getElementById('toggle-password');
  var passwordInput = document.getElementById('password');
  toggle.addEventListener('click', function () {
    var show = passwordInput.type === 'password';
    passwordInput.type = show ? 'text' : 'password';
    toggle.textContent = show ? 'Ocultar' : 'Mostrar';
    toggle.setAttribute('aria-pressed', show ? 'true' : 'false');
  });
})();
</script>
</body>
